sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;700;800&family=Share+Tech+Mono&family=DM+Sans:wght@300;400;500&display=swap');

.nx-page { background: #08080f; color: #f0ecff; font-family: 'DM Sans', sans-serif; min-height: 100vh; }

/* NAV */
.nx-nav {
  display: flex; justify-content: space-between; align-items: center;
  padding: 0 60px; height: 68px;
  border-bottom: 1px solid rgba(184,122,255,0.12);
  background: rgba(8,8,15,0.95);
  position: sticky; top: 0; z-index: 100;
}
.nx-logo { font-family: 'Syne', sans-serif; font-size: 1.45rem; font-weight: 800; color: #f0ecff; letter-spacing: 0.04em; }
.nx-logo span { color: #b87aff; text-shadow: 0 0 24px rgba(184,122,255,0.5); }
.nx-nav-links { display: flex; gap: 36px; }
.nx-nav-links a {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.9rem; letter-spacing: 0.14em; text-transform: uppercase;
  color: rgba(240,236,255,0.55); text-decoration: none; transition: color 0.3s;
}
.nx-nav-links a:hover { color: #b87aff; text-decoration: none; }

/* HERO SMALL */
.nx-hero {
  padding: 60px 60px 50px; position: relative;
  overflow: hidden; background: #08080f;
  border-bottom: 1px solid rgba(184,122,255,0.12);
}
.nx-hero-sm { padding: 48px 60px 40px; }
.nx-hero-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(184,122,255,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(184,122,255,0.04) 1px, transparent 1px);
  background-size: 48px 48px; pointer-events: none;
}
.nx-hero::before {
  content: ''; position: absolute;
  width: 600px; height: 400px; border-radius: 50%;
  background: radial-gradient(circle, rgba(184,122,255,0.07) 0%, transparent 65%);
  top: -150px; right: -80px; pointer-events: none;
}
.nx-hero-content { position: relative; z-index: 2; max-width: 680px; }
.nx-eyebrow {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.85rem; letter-spacing: 0.28em; color: #b87aff;
  text-transform: uppercase; margin-bottom: 16px;
  display: flex; align-items: center; gap: 12px;
}
.nx-eyebrow::before {
  content: ''; display: inline-block; width: 20px; height: 1px;
  background: #b87aff; opacity: 0.6;
}
.nx-hero h1 {
  font-family: 'Syne', sans-serif; font-size: 3.2rem;
  font-weight: 800; line-height: 1.05; color: #f0ecff; margin-bottom: 16px;
}
.nx-accent { color: #b87aff; text-shadow: 0 0 32px rgba(184,122,255,0.45); }
.nx-dot { color: #ffb899; }
.nx-sub { font-size: 1rem; color: rgba(240,236,255,0.55); font-weight: 300; line-height: 1.75; }
/* STATS ROW */
.nx-res-stats {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 16px; padding: 32px 60px 0; background: #08080f;
}
.nx-res-stat-card {
  background: #0e0c1a; border: 1px solid rgba(184,122,255,0.12);
  border-radius: 12px; padding: 24px 28px;
  transition: border-color 0.3s;
}
.nx-res-stat-card:hover { border-color: rgba(184,122,255,0.3); }
.nx-res-stat-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.75rem; letter-spacing: 0.2em; text-transform: uppercase;
  color: rgba(240,236,255,0.35); display: block; margin-bottom: 10px;
}
.nx-res-stat-num {
  font-family: 'Syne', sans-serif; font-size: 2.4rem;
  font-weight: 800; line-height: 1; display: block;
}
.nx-col-green  { color: #7fffb2; text-shadow: 0 0 20px rgba(127,255,178,0.4); }
.nx-col-purple { color: #b87aff; text-shadow: 0 0 20px rgba(184,122,255,0.4); }
.nx-col-peach  { color: #ffb899; text-shadow: 0 0 20px rgba(255,184,153,0.4); }
.nx-col-white  { color: #f0ecff; }

/* RESERVATIONS SECTION */
.nx-res-section { padding: 32px 60px 60px; background: #08080f; }
.nx-section-header { display: flex; align-items: center; gap: 14px; margin-bottom: 24px; }
.nx-tag {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.8rem; letter-spacing: 0.2em; text-transform: uppercase;
  color: #b87aff; background: rgba(184,122,255,0.14);
  border: 1px solid rgba(184,122,255,0.24); padding: 5px 14px; border-radius: 3px;
}
.nx-section-line { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(184,122,255,0.12), transparent); }
.nx-section-count { font-family: 'Share Tech Mono', monospace; font-size: 0.82rem; color: rgba(240,236,255,0.28); }

/* EMPTY STATE */
.nx-empty {
  text-align: center; padding: 80px 40px;
  border: 1px solid rgba(184,122,255,0.12);
  border-radius: 12px; background: #0e0c1a;
}
.nx-empty-icon { font-size: 3rem; display: block; margin-bottom: 16px; }
.nx-empty-text { font-size: 1rem; color: rgba(240,236,255,0.4); margin-bottom: 28px; }

/* BUTTON */
.nx-btn-primary {
  display: inline-flex; align-items: center; gap: 10px;
  background: transparent; border: 1.5px solid #b87aff; color: #b87aff;
  font-family: 'Share Tech Mono', monospace; font-size: 0.85rem;
  letter-spacing: 0.18em; text-transform: uppercase;
  padding: 15px 32px; border-radius: 4px; text-decoration: none; transition: all 0.3s;
}
.nx-btn-primary:hover { background: rgba(184,122,255,0.14); color: #b87aff; text-decoration: none; }
/* RESERVATIONS TABLE */
.nx-res-table-wrap {
  overflow-x: auto;
  border: 1px solid rgba(184,122,255,0.12);
  border-radius: 12px; background: #0e0c1a;
}
.nx-res-table {
  width: 100%; border-collapse: collapse;
  font-size: 0.88rem;
}
.nx-res-table thead tr {
  border-bottom: 1px solid rgba(184,122,255,0.15);
  background: rgba(184,122,255,0.06);
}
.nx-res-table th {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.7rem; letter-spacing: 0.2em;
  text-transform: uppercase; color: rgba(240,236,255,0.35);
  padding: 16px 20px; text-align: left; font-weight: 400;
}
.nx-res-row {
  border-bottom: 1px solid rgba(255,255,255,0.04);
  transition: background 0.2s;
}
.nx-res-row:last-child { border-bottom: none; }
.nx-res-row:hover { background: rgba(184,122,255,0.05); }
.nx-res-table td { padding: 16px 20px; vertical-align: middle; }
.nx-res-num {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.82rem; color: #b87aff;
  text-decoration: none; letter-spacing: 0.05em;
  transition: opacity 0.2s;
}
.nx-res-num:hover { opacity: 0.7; text-decoration: none; }
.nx-res-workspace { color: #f0ecff; font-weight: 500; }
.nx-res-date {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.78rem; color: rgba(240,236,255,0.5);
}
.nx-res-location { color: rgba(240,236,255,0.55); font-size: 0.85rem; }

/* STATUS BADGES */
.nx-res-badge {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.65rem; letter-spacing: 0.12em;
  text-transform: uppercase; padding: 4px 12px;
  border-radius: 3px; border: 1px solid; white-space: nowrap;
}
.nx-badge-av   { color: #7fffb2; border-color: rgba(127,255,178,0.25); background: rgba(127,255,178,0.07); }
.nx-badge-un   { color: #ff6b6b; border-color: rgba(255,107,107,0.25); background: rgba(255,107,107,0.07); }
.nx-badge-done { color: #b87aff; border-color: rgba(184,122,255,0.25); background: rgba(184,122,255,0.07); }

/* FOOTER */
.nx-footer {
  border-top: 1px solid rgba(184,122,255,0.12);
  padding: 24px 60px; display: flex;
  justify-content: space-between; align-items: center;
  background: #08080f;
}
.nx-footer-logo { font-family: 'Syne', sans-serif; font-size: 0.9rem; font-weight: 700; color: rgba(240,236,255,0.28); }
.nx-footer-logo span { color: #b87aff; }
.nx-footer-copy { font-family: 'Share Tech Mono', monospace; font-size: 0.72rem; color: rgba(240,236,255,0.28); letter-spacing: 0.15em; }

/* RESPONSIVE */
@media (max-width: 900px) {
  .nx-nav, .nx-hero, .nx-res-stats, .nx-res-section, .nx-footer { padding-left: 20px; padding-right: 20px; }
  .nx-res-stats { grid-template-columns: repeat(2, 1fr); }
  .nx-hero h1 { font-size: 2.4rem; }
}
@media (max-width: 600px) {
  .nx-res-stats { grid-template-columns: 1fr; }
}

sp_widget.script:
(function() {
	data.catalogItemId = '2ab07725c3eb32109f0231cc050131f6';

    // Get logged in user's reservations
    var reservations = [];
    var gr = new GlideRecord('x_746154_workspa_0_reservation_tracker');
    gr.addQuery('reserved_for', gs.getUserID());
    gr.orderByDesc('start_date_time');
    gr.query();

    while (gr.next()) {
        reservations.push({
            number:            gr.getDisplayValue('number'),
            workspace:         gr.getDisplayValue('workspace'),
            status:            gr.getDisplayValue('reservation_status'),
            state:             gr.getDisplayValue('state'),
            startDate:         gr.getDisplayValue('start_date_time'),
            endDate:           gr.getDisplayValue('end_date_time'),
            location:          gr.getDisplayValue('location'),
            sysId:             gr.getUniqueValue()
        });
    }

    data.reservations  = reservations;
    data.totalCount    = reservations.length;
    data.userName      = gs.getUser().getFirstName() || gs.getUserDisplayName();

    // Count by status
    var active = 0, completed = 0, cancelled = 0;
    for (var i = 0; i < reservations.length; i++) {
        var s = reservations[i].status.toLowerCase().replace(/ /g, '_');
        if (s === 'pending_check_in' || s === 'checked_in') active++;
        else if (s === 'checked_out') completed++;
        else if (s === 'cancelled' || s === 'no_show') cancelled++;
    }
    data.activeCount    = active;
    data.completedCount = completed;
    data.cancelledCount = cancelled;

})();
